 }
 function Station(id,production){
  foreach(tile in Candidates(id,production)){
   if(!production && origin_tile>=0 && GSMap.DistanceManhattan(tile,origin_tile)<MIN_SEPARATION)continue;
   if(MODE=="ship"){
    if(!GSTile.IsCoastTile(tile))continue;
    local tm=GSTestMode(),ok=GSMarine.BuildDock(tile,GSStation.STATION_NEW);tm=null;
    if(ok && GSMarine.BuildDock(tile,GSStation.STATION_NEW))return tile;
   }else{
    if(!GSTile.IsBuildable(tile) && !(MODE=="road" && GSRoad.IsRoadTile(tile)))continue;
    if(MODE=="road" && !GSTile.IsBuildable(Step(tile,-1,0)) && !GSRoad.IsRoadTile(Step(tile,-1,0)))continue;
    if(MODE=="rail" && (!GSTile.IsBuildable(Step(tile,-2,0)) || !GSTile.IsBuildable(Step(tile,-1,0)) || !GSTile.IsBuildable(Step(tile,2,0)) || !GSTile.IsBuildable(Step(tile,3,0))))continue;
    local front=Step(tile,-1,0),tm=GSTestMode();
    local ok=MODE=="rail"?GSRail.BuildRailStation(tile,GSRail.RAILTRACK_NE_SW,1,2,GSStation.STATION_NEW):GSRoad.BuildDriveThroughRoadStation(tile,front,CARGO==0?GSRoad.ROADVEHTYPE_BUS:GSRoad.ROADVEHTYPE_TRUCK,GSStation.STATION_NEW);
    tm=null;
    if(!ok)continue;
    if(!production && origin_tile>=0){
     local trial=Path(Step(origin_tile,-1,0),origin_tile,Step(tile,MODE=="rail"?2:-1,0));
     if(trial==null)continue;
    }
    ok=MODE=="rail"?GSRail.BuildRailStation(tile,GSRail.RAILTRACK_NE_SW,1,2,GSStation.STATION_NEW):GSRoad.BuildDriveThroughRoadStation(tile,front,CARGO==0?GSRoad.ROADVEHTYPE_BUS:GSRoad.ROADVEHTYPE_TRUCK,GSStation.STATION_NEW);
    if(ok)return tile;
   }
  }
