 function Tile(x,y){return GSMap.GetTileIndex(x,y);}
 function Fail(s){GSLog.Info("P3_BLOCKED|"+CASE+"|"+s+"|"+GSError.GetLastErrorString());}
 function Step(t,dx,dy){return Tile(GSMap.GetTileX(t)+dx,GSMap.GetTileY(t)+dy);}
