   local node=nodes[pos];
   if(node.tile==goal){local path=[];local i=pos;while(i>=0){path.insert(0,nodes[i].tile);i=nodes[i].backidx;}return path;}
   foreach(delta in [[1,0],[-1,0],[0,1],[0,-1]]){
    local x=GSMap.GetTileX(node.tile)+delta[0],y=GSMap.GetTileY(node.tile)+delta[1];
