    local income=0,expenses=0,delivered=0;for(local q=1;q<=4;q++){income+=GSCompany.GetQuarterlyIncome(0,q);expenses+=GSCompany.GetQuarterlyExpenses(0,q);delivered+=GSCompany.GetQuarterlyCargoDelivered(0,q);}
